-- Health screening, medication, counselling, welfare cases; certificate templates and issued certificates.
ALTER TABLE public.student_health ADD COLUMN updated_on DATE NOT NULL DEFAULT CURRENT_DATE;
CREATE TABLE public.health_screenings (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, height_cm INTEGER CHECK (height_cm BETWEEN 30 AND 250), weight_kg NUMERIC(5,1) CHECK (weight_kg BETWEEN 3 AND 250), vision VARCHAR(60) NOT NULL DEFAULT '', checkup VARCHAR(80) NOT NULL DEFAULT '', screened_on DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(16) NOT NULL DEFAULT 'Normal' CHECK (status IN ('Normal', 'Needs attention', 'Referred')));
CREATE TABLE public.medication_records (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, medicine VARCHAR(80) NOT NULL, dose_when VARCHAR(60) NOT NULL, until DATE NOT NULL, consent BOOLEAN NOT NULL DEFAULT false, status VARCHAR(8) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Stopped')));
CREATE TABLE public.medication_doses (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), medication_id UUID NOT NULL REFERENCES public.medication_records(id) ON DELETE CASCADE, given_at TIMESTAMPTZ NOT NULL DEFAULT now(), given_by VARCHAR(80) NOT NULL DEFAULT '');
CREATE TABLE public.counselling_sessions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, session_at TIMESTAMPTZ NOT NULL, referred_by VARCHAR(60) NOT NULL, counsellor VARCHAR(80) NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'Scheduled' CHECK (status IN ('Scheduled', 'Done', 'Missed')));
CREATE SEQUENCE public.welfare_case_seq START 43;
CREATE TABLE public.welfare_cases (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(10) NOT NULL DEFAULT ('RF-' || lpad(nextval('public.welfare_case_seq')::text, 4, '0')), student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, referred_to VARCHAR(120) NOT NULL, owner VARCHAR(80) NOT NULL, opened_on DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(8) NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'Closed')));
CREATE TABLE public.cert_templates (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(80) NOT NULL, size VARCHAR(8) NOT NULL DEFAULT 'A4' CHECK (size IN ('A4', 'A5', 'Letter')), signed_by VARCHAR(40) NOT NULL DEFAULT 'Principal', last_edited DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(8) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Inactive')), UNIQUE (institution_id, name));
CREATE TABLE public.certificates (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, kind VARCHAR(12) NOT NULL CHECK (kind IN ('Bonafide', 'Study', 'Conduct', 'Character')), code VARCHAR(30) NOT NULL, student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, purpose VARCHAR(120) NOT NULL DEFAULT '', issued_on DATE NOT NULL DEFAULT CURRENT_DATE, UNIQUE (institution_id, code));
ALTER TABLE public.health_screenings ENABLE ROW LEVEL SECURITY; ALTER TABLE public.medication_records ENABLE ROW LEVEL SECURITY; ALTER TABLE public.medication_doses ENABLE ROW LEVEL SECURITY; ALTER TABLE public.counselling_sessions ENABLE ROW LEVEL SECURITY; ALTER TABLE public.welfare_cases ENABLE ROW LEVEL SECURITY; ALTER TABLE public.cert_templates ENABLE ROW LEVEL SECURITY; ALTER TABLE public.certificates ENABLE ROW LEVEL SECURITY;
